// PageMeta defines model for PageMeta.
type PageMeta struct {
	// DataAsOf How current the data is. Stats-derived data (scores, matchups,
	// lineups with points, players): while a match is live, the last
	// good poll of the stats feed; between matches, while the poller
	// keeps its schedule (no failed poll and the next poll not overdue
	// by 3 minutes), the server time, because nothing upstream moves;
	// while the poller fails or has stopped, the last good poll. League
	// state (drafts, claims, trades, settings): the server time.
	DataAsOf time.Time `json:"dataAsOf"`

	// NextCursor Null on the last page.
	NextCursor *string `json:"nextCursor"`

	// ScoreState Open enum. `upcoming`: no match has kicked off. `live`: matches in
	// progress. `provisional`: matches done, bonus not yet added.
	// `official`: bonus added. `final`: the stats feed has checked the
	// data. From `provisional` on the result counts in the standings, with
	// provisional bonus; a later bonus or stats change rescores it.
	ScoreState *ScoreState `json:"scoreState,omitempty"`

	// ServerTime The server clock when this response was built. Age `dataAsOf`
	// against this, not the device clock.
	ServerTime time.Time `json:"serverTime"`

	// Stale True when stats-derived data may be behind: a live match's data
	// 3 minutes after the last good poll, otherwise when the poller is
	// failing or more than 3 minutes past its scheduled poll.
	Stale bool `json:"stale"`

	// StaleAt Stats-derived data only: when this data turns stale unless a
	// newer poll lands, on the server clock. The poller's next
	// scheduled poll plus 3 minutes (while a match is live, the last
	// good poll plus 3 minutes), so between match days, when the
	// poller sleeps for hours, a client keeps the data fresh until
	// then. Absent for league state, which never goes stale upstream.
	StaleAt *time.Time `json:"staleAt,omitempty"`
}

