// ShadowCheck The latest automatic, read-only comparison with FPL Draft (a shadow
// check), run from the FPL calendar until the switch-over: after the
// waiver run, around each deadline, at each match's kickoff, half
// time, full time and bonus, and when FPL marks the data checked. It
// never changes the league. A difference on data FPL has not
// finalized (a live match, bonus not added) is `pending`; it is a
// `mismatch` only once final, and the commissioner is notified
// (`fpl_check_mismatch`).
type ShadowCheck struct {
	CheckedAt time.Time       `json:"checkedAt"`
	Counts    SyncItemCounts  `json:"counts"`
	Gameweek  *GameweekNumber `json:"gameweek"`

	// Mismatches Differences on finalized data, with the team, player and numbers.
	Mismatches []SyncItem `json:"mismatches"`

	// Pending Differences FPL may still resolve (live data).
	Pending []SyncItem `json:"pending"`

	// Reason Open enum: after_waivers, before_deadline, after_deadline, kickoff, half_time, full_time, bonus, data_checked, admin.
	Reason string `json:"reason"`

	// Status Open enum. `incomplete`: nothing disagrees, but some items could not be checked yet.
	Status SyncReportStatus `json:"status"`
}

